public:
    string decodeString(string s) {
        stack<int> numStack;
        stack<string> strStack;
        string curStr = "";
        int curNum = 0;
        for (char ch : s) {
            if (isdigit(ch)) curNum = curNum * 10 + (ch - '0');
            else if (ch == '[') { numStack.push(curNum); strStack.push(curStr); curNum = 0; curStr = ""; }
            else if (ch == ']') { int r = numStack.top(); numStack.pop(); string prev = strStack.top(); strStack.pop(); string tmp = ""; for (int i = 0; i < r; i++) tmp += curStr; curStr = prev + tmp; }
            else curStr += ch;
        }
        return curStr;
    }
};

