class Solution {
    public String decodeString(String s) {
        Stack<Integer> numStack = new Stack<>();
        Stack<StringBuilder> strStack = new Stack<>();
        StringBuilder curStr = new StringBuilder();
        int curNum = 0;
        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) curNum = curNum * 10 + (ch - '0');
            else if (ch == '[') { numStack.push(curNum); strStack.push(curStr); curNum = 0; curStr = new StringBuilder(); }
            else if (ch == ']') { int r = numStack.pop(); StringBuilder prev = strStack.pop(); for (int i = 0; i < r; i++) prev.append(curStr); curStr = prev; }
            else curStr.append(ch);
        }
        return curStr.toString();
    }
}

