        while (idx < (int)s.size()) {
            char ch = s[idx];
            if (isdigit(ch)) { num = num * 10 + (ch - '0'); idx++; }
            else if (ch == '[') { idx++; string inner = dfs(s); for (int i = 0; i < num; i++) res += inner; num = 0; }
            else if (ch == ']') { idx++; return res; }
            else { res += ch; idx++; }
        }
        return res;
    }
};

