class Solution:
    def decodeString(self, s: str) -> str:
        self.i = 0
        def dfs():
            res = ''
            num = 0
            while self.i < len(s):
                ch = s[self.i]
                if ch.isdigit():
                    num = num * 10 + int(ch)
                    self.i += 1
                elif ch == '[':
                    self.i += 1
                    inner = dfs()
                    res += inner * num
                    num = 0
                elif ch == ']':
                    self.i += 1
                    return res
                else:
                    res += ch
                    self.i += 1
            return res
        return dfs()

