class Solution {
    int idx = 0;
    public String decodeString(String s) { idx = 0; return dfs(s); }
    private String dfs(String s) {
        StringBuilder res = new StringBuilder();
        int num = 0;
        while (idx < s.length()) {
            char ch = s.charAt(idx);
            if (Character.isDigit(ch)) { num = num * 10 + (ch - '0'); idx++; }
            else if (ch == '[') { idx++; String inner = dfs(s); for (int i = 0; i < num; i++) res.append(inner); num = 0; }
            else if (ch == ']') { idx++; return res.toString(); }
            else { res.append(ch); idx++; }
        }
        return res.toString();
    }
}
